//import { AnyAction } from "redux-saga";



export type ActionWithPayload<T, P> = {
    type: T;
    payload: P;
};

export type Action<T> = {
    type: T;
};

export function createAction<T extends string, P>(typeVal: T, payloadVal: P): ActionWithPayload<T, P>;

export function createAction<T extends string>(typeVal: T, payloadVal: void): Action<T>;

export function createAction<T extends string, P>(typeVal: T, payloadVal: P) {
    return {
        type: typeVal,
        payload: payloadVal,
    }
};
